module med21 (
  input clk, input rst_n, input [7:0] x, output reg [15:0] y
);
  reg [7:0] win [0:20];
  integer i, j, mid, lt, gt;
  reg [7:0] tmp;
  always @(posedge clk) begin
    if (!rst_n) begin
      for (i = 0; i < 21; i = i + 1) win[i] <= 8'd0;
      y <= 16'd0;
    end else begin
      for (i = 1; i < 21; i = i + 1) win[i] <= win[i-1];
      win[0] <= x;
      for (i = 0; i < 20; i = i + 1) begin
        for (j = i + 1; j < 21; j = j + 1) begin
          if (win[i] > win[j]) begin
            tmp <= win[i];
            win[i] <= win[j];
            win[j] <= tmp;
          end
        end
      end
      mid <= 13;
      lt = 0; gt = 0;
      while (lt + gt < 10) begin
        if (win[mid] > win[19]) gt = gt + 1;
        else lt = lt + 1;
        if (lt == mid) mid = mid + 1;
        else if (gt == (20 - mid)) mid = mid - 1;
      end
      y <= {8'd0, win[mid]};
    end
  end
endmodule

